inline std::optional<Vec> vehicleModelSize(int model){
    if(model<400||model>611)return {};
    return vehicleModelSizes[model-400];
}
inline std::array<std::optional<Vec>,212> vehiclePeerEnvelopes(){
    std::array<std::optional<Vec>,212> result;
    for(int i=0;i<212;i++){
        const auto size=vehicleModelSizes[i];
        // The API supplies total size but no bounding-box centre offset.
        // Use full dimensions as half-extents for a conservative peer volume;
        // the sensor encloses that volume in a sphere for arbitrary rotation.
        // This is intentionally larger than half the reported dimensions.
        result[i]=Vec{size.y+.25,size.x+.25,size.z+.25};
    }
    return result;
}
